BEGIN;
SET search_path TO stridebr, public;

ALTER TABLE exercicios ADD COLUMN IF NOT EXISTS equipamento VARCHAR(40);
ALTER TABLE exercicios ADD COLUMN IF NOT EXISTS tipo_registro VARCHAR(24) NOT NULL DEFAULT 'load_reps';
ALTER TABLE exercicios DROP CONSTRAINT IF EXISTS ck_exercicios_tipo_registro;
ALTER TABLE exercicios ADD CONSTRAINT ck_exercicios_tipo_registro CHECK (tipo_registro IN ('load_reps','reps','duration','distance','duration_distance'));

CREATE TABLE IF NOT EXISTS exercicios_aliases (
    idalias BIGSERIAL PRIMARY KEY,
    idexercicio VARCHAR(21) NOT NULL REFERENCES exercicios(idexercicio) ON DELETE CASCADE,
    alias VARCHAR(160) NOT NULL CHECK (length(trim(alias)) > 0),
    alias_normalizado VARCHAR(180) NOT NULL CHECK (length(trim(alias_normalizado)) > 0),
    idioma VARCHAR(16) NOT NULL DEFAULT 'und',
    seguro BOOLEAN NOT NULL DEFAULT FALSE,
    data_criacao TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (idexercicio, alias_normalizado)
);
CREATE INDEX IF NOT EXISTS ix_exercicios_aliases_normalizado ON exercicios_aliases (alias_normalizado);

CREATE TEMP TABLE exercise_library_v2_seed (
    idexercicio VARCHAR(21) PRIMARY KEY,
    nome VARCHAR(120) NOT NULL,
    slug VARCHAR(140) NOT NULL,
    equipamento VARCHAR(40),
    tipo_registro VARCHAR(24) NOT NULL,
    primarios JSONB NOT NULL,
    secundarios JSONB NOT NULL
) ON COMMIT DROP;


UPDATE exercicios e
SET nome=s.nome,
    equipamento=s.equipamento,
    tipo_registro=s.tipo_registro,
    grupos_musculares_primarios=s.primarios,
    grupos_musculares_secundarios=s.secundarios,
    ativo=TRUE,
    data_atualizacao=NOW()
FROM exercise_library_v2_seed s
WHERE e.idusuario IS NULL AND lower(e.slug)=lower(s.slug);

SELECT s.idexercicio,NULL,s.nome,s.slug,NULL,TRUE,'publico','publicado',s.equipamento,s.tipo_registro,s.primarios,s.secundarios
FROM exercise_library_v2_seed s
WHERE NOT EXISTS (SELECT 1 FROM exercicios e WHERE e.idusuario IS NULL AND lower(e.slug)=lower(s.slug));

CREATE TEMP TABLE exercise_library_v2_alias_seed (
    target_slug VARCHAR(140) NOT NULL,
    alias VARCHAR(160) NOT NULL,
    alias_normalizado VARCHAR(180) NOT NULL,
    idioma VARCHAR(16) NOT NULL,
    seguro BOOLEAN NOT NULL
) ON COMMIT DROP;

SELECT e.idexercicio,a.alias,a.alias_normalizado,a.idioma,a.seguro
FROM exercise_library_v2_alias_seed a
JOIN exercicios e ON e.idusuario IS NULL AND lower(e.slug)=lower(a.target_slug)
ON CONFLICT (idexercicio,alias_normalizado) DO UPDATE SET alias=EXCLUDED.alias, idioma=EXCLUDED.idioma, seguro=EXCLUDED.seguro;

COMMIT;
